namespace ghidra.app.plugin.core.analysis;

using ghidra.app.services;
using ghidra.app.util.importer;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * {@link Analyzer} to link unresolved external symbols
 * 
 * @see ExternalSymbolResolver
 */
public class ExternalSymbolResolverAnalyzer : AbstractAnalyzer {

	private static readonly string NAME = "External Symbol Resolver";
	private static readonly string DESCRIPTION =
		"Links unresolved external symbols to the first symbol found in the program's required libraries list (found in program properties).";

	/**
	 * Creates a new {@link ExternalSymbolResolverAnalyzer} 
	 */
	public ExternalSymbolResolverAnalyzer() : base(NAME, DESCRIPTION, AnalyzerType.BYTE_ANALYZER)
    {
		setDefaultEnablement(true);
		setSupportsOneTimeAnalysis();

		// Do it before demangling
		setPriority(AnalysisPriority.DATA_TYPE_PROPOGATION.before().before().before().before());
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		// This analyzer needs to look around the project for imported libraries
		if (program.getDomainFile().getParent() == null) {
			return false;
		}

		return program.getSymbolTable().getLibrarySymbol(Library.UNKNOWN) != null;
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {

		using (ExternalSymbolResolver esr = new ExternalSymbolResolver(
			program.getDomainFile().getParent().getProjectData(), monitor))
{
			esr.addProgramToFixup(program);
			esr.fixUnresolvedExternalSymbols();
			esr.logInfo(s => Msg.info(this, s), false);
			if (esr.hasProblemLibraries()) {
				// causes a popup message at end of analysis session
				esr.logInfo(log.appendMsg, true);
			}
			return true;
		}
	}
}
